import { computed, type Ref } from "vue";
import { useAxios, type UseAxiosOptions } from "@vueuse/integrations/useAxios";
import { createEventHook, whenever } from "@vueuse/core";
import { useApiInstance } from "./useApiInstance";

export interface BackendResponse<T> {
  result: T;
  error?: {
    data: {
      message: string;
    };
    message?: string;
  };
}

export function useApi<T>(path: string = "", options: UseAxiosOptions<T> = {}) {
  const { immediate = false, ...axiosOptions } = options;
  const initialData = (options as any).initialData;

  const instance = useApiInstance();

  const query = useAxios<BackendResponse<T>>(
    path,
    { ...axiosOptions, initialData } as any,
    instance,
    { immediate },
  );

  const onResultSuccess = createEventHook<T>();
  const onResultError = createEventHook<string>();

  const result = computed<T | undefined>(() => {
    if (!query.data.value) return initialData as unknown as T;
    return query.data.value.result ?? (initialData as unknown as T);
  });

  const resultError = computed<string | undefined>(() => {
    if (query.error.value) {
      return query.error.value instanceof Error
        ? query.error.value.message
        : String(query.error.value);
    }

    if (query.data.value?.error) {
      return (
        query.data.value.error.data?.message ||
        query.data.value.error.message ||
        "Unknown API Error"
      );
    }

    return undefined;
  });

  whenever(query.isFinished, () => {
    const data = query.data.value;
    const error = query.error.value;

    if (error) {
      onResultError.trigger(error instanceof Error ? error.message : String(error));
    } else if (data) {
      if (data.error) {
        onResultError.trigger(data.error.data?.message || data.error.message || "API Error");
      } else {
        (onResultSuccess.trigger as any)(data.result);
      }
    } else {
      onResultError.trigger("Request finished with no data");
    }
  });

  return {
    ...query,
    result,
    resultError,
    onResultSuccess: onResultSuccess.on,
    onResultError: onResultError.on,
    execute: query.execute,
  };
}
