import { computed, isRef, ref, unref, watch, type Ref } from "vue";
import { useReactiveQuery } from "./useReactiveQuery";
import type { ListOpts, Repository, Row, TableName } from "@/shared/database/repository/types";

type WriteMethod = "insert" | "update" | "softDelete" | "upsertMany";

export function reactiveRepo<T extends TableName>(repo: Repository<T>) {
  function useList(opts?: ListOpts<T>) {
    const query = useReactiveQuery<Row<T>[]>(() => repo.list(opts), {
      tables: [repo.table],
      queryKey: `${repo.table}:list`,
    });

    return {
      ...query,
      data: computed<Row<T>[]>(() => query.data.value ?? []),
    };
  }

  function useGet(idRef: Ref<number> | number) {
    const id = isRef(idRef) ? idRef : ref(idRef);

    const query = useReactiveQuery<Row<T> | undefined>(() => repo.getById(unref(id)), {
      tables: [repo.table],
      queryKey: `${repo.table}:get:${unref(id)}`,
    });

    watch(id, () => {
      void query.refetch();
    });

    return query;
  }

  function useQuery<R>(fn: () => Promise<R>, options: { key: string; tables: string[] }) {
    return useReactiveQuery<R>(fn, {
      tables: options.tables,
      queryKey: options.key,
    });
  }

  function useMutation<M extends WriteMethod>(method: M) {
    const pending = ref(false);
    const error = ref<Error | null>(null);

    async function execute(...args: Parameters<Repository<T>[M]>): Promise<void> {
      pending.value = true;
      error.value = null;
      try {
        await (repo[method] as (...a: unknown[]) => Promise<unknown>)(...args);
      } catch (err) {
        error.value = err instanceof Error ? err : new Error(String(err));
        throw err;
      } finally {
        pending.value = false;
      }
    }

    return { execute, pending, error };
  }

  return { useList, useGet, useQuery, useMutation };
}
