import type { Kysely } from "kysely";
import type { Database } from "@/shared/database/global.schema";
import { dbService } from "@/shared/database/DatabaseService";
import { rdb } from "@/shared/database/reactive/reactiveDb";
import { generateLocalRuid, nowISO, type SyncStatus } from "@/shared/database/migrations/_helpers";
import type { ListOpts, NewRow, Repository, Row, RowPatch, TableName } from "./types";

const UPSERT_CHUNK_SIZE = 200;

function readDb(): Kysely<Database> {
  return dbService.getDb();
}

export function createRepository<T extends TableName>(table: T): Repository<T> {
  async function getById(id: number): Promise<Row<T> | undefined> {
    const query = readDb().selectFrom(table).selectAll() as any;
    return (await query.where("id", "=", id).executeTakeFirst()) as Row<T> | undefined;
  }

  async function getByRuid(ruid: string): Promise<Row<T> | undefined> {
    const query = readDb().selectFrom(table).selectAll() as any;
    return (await query.where("_ruid", "=", ruid).executeTakeFirst()) as Row<T> | undefined;
  }

  async function list(opts?: ListOpts<T>): Promise<Row<T>[]> {
    let query = readDb().selectFrom(table).selectAll() as any;

    if (!opts?.includeDeleted) {
      query = query.where("_delete_date", "is", null);
    }
    if (opts?.orderBy) {
      query = query.orderBy(opts.orderBy.column, opts.orderBy.direction ?? "asc");
    }
    if (opts?.limit != null) {
      query = query.limit(opts.limit);
    }
    if (opts?.offset != null) {
      query = query.offset(opts.offset);
    }

    return (await query.execute()) as Row<T>[];
  }

  async function findWhere(where: Partial<Row<T>>): Promise<Row<T>[]> {
    let query = readDb().selectFrom(table).selectAll() as any;
    for (const [column, value] of Object.entries(where)) {
      query = query.where(column, "=", value);
    }
    return (await query.execute()) as Row<T>[];
  }

  async function insert(row: NewRow<T>): Promise<Row<T>> {
    const source = row as Record<string, unknown>;
    const values = {
      ...source,
      _ruid: source._ruid ?? generateLocalRuid(),
      _create_date: source._create_date ?? nowISO(),
      _write_date: source._write_date ?? nowISO(),
      _sync_status: "to_create" satisfies SyncStatus,
    };

    await (rdb.insertInto(table) as any).values(values).executeTakeFirstOrThrow();

    const created = await getByRuid(values._ruid as string);
    if (!created) {
      throw new Error(`[${table}] insert succeeded but row not found`);
    }
    return created;
  }

  async function update(id: number, patch: RowPatch<T>): Promise<Row<T>> {
    const current = await getById(id);
    const wasLocalOnly =
      (current as Record<string, unknown> | undefined)?._sync_status === "to_create";

    const values = {
      ...(patch as Record<string, unknown>),
      _write_date: nowISO(),
      _sync_status: (wasLocalOnly ? "to_create" : "to_update") satisfies SyncStatus,
    };

    await (rdb.updateTable(table) as any).set(values).where("id", "=", id).execute();

    const updated = await getById(id);
    if (!updated) {
      throw new Error(`[${table}] update succeeded but row not found`);
    }
    return updated;
  }

  async function softDelete(id: number): Promise<void> {
    const current = await getById(id);
    const isLocalOnly =
      (current as Record<string, unknown> | undefined)?._sync_status === "to_create";

    if (isLocalOnly) {
      await (rdb.deleteFrom(table) as any).where("id", "=", id).execute();
      return;
    }

    await (rdb.updateTable(table) as any)
      .set({
        _delete_date: nowISO(),
        _write_date: nowISO(),
        _sync_status: "to_delete" satisfies SyncStatus,
      })
      .where("id", "=", id)
      .execute();
  }

  async function upsertMany(rows: NewRow<T>[], status: SyncStatus = "synced"): Promise<void> {
    if (rows.length === 0) return;

    for (let start = 0; start < rows.length; start += UPSERT_CHUNK_SIZE) {
      const chunk = rows.slice(start, start + UPSERT_CHUNK_SIZE).map((row) => {
        const source = row as Record<string, unknown>;
        return {
          ...source,
          _create_date: source._create_date ?? nowISO(),
          _write_date: source._write_date ?? nowISO(),
          _sync_status: status,
        };
      });

      const columns = Object.keys(chunk[0]!).filter(
        (column) => column !== "id" && column !== "_ruid",
      );

      await (rdb.insertInto(table) as any)
        .values(chunk)
        .onConflict((oc: any) =>
          oc.column("_ruid").doUpdateSet((eb: any) => {
            const assignments: Record<string, unknown> = {};
            for (const column of columns) {
              assignments[column] = eb.ref(`excluded.${column}`);
            }
            return assignments;
          }),
        )
        .execute();
    }
  }

  async function query<R>(fn: (db: Kysely<Database>) => Promise<R>): Promise<R> {
    return await fn(readDb());
  }

  return {
    table,
    list,
    getById,
    getByRuid,
    findWhere,
    insert,
    update,
    softDelete,
    upsertMany,
    query,
  };
}
