import { ref } from "vue";
import type { OptimisticMutationOptions } from "@/shared/database/reactive/types";

export function useOptimisticMutation<T, R, S = unknown>(
  options: OptimisticMutationOptions<T, R, S>,
) {
  const loading = ref(false);
  const error = ref<Error | null>(null);

  async function mutate(data: T): Promise<R | null> {
    loading.value = true;
    error.value = null;
    const snapshot = options.snapshot?.();

    try {
      options.optimisticUpdate(data);
      const result = await options.mutation(data);

      if (options.onSuccess) {
        options.onSuccess(result);
      }

      loading.value = false;
      return result;
    } catch (err) {
      error.value = err instanceof Error ? err : new Error(String(err));
      await options.rollback?.(snapshot, data, err);

      if (options.onError) {
        options.onError(err);
      } else {
        console.error(`[Optimistic Mutation] Failed for table "${options.table}":`, err);
      }

      loading.value = false;
      return null;
    }
  }

  return {
    mutate,
    loading,
    error,
  };
}

export function useOptimisticDelete<T, ID>(options: {
  table: string;
  items: { value: T[] };
  findFn: (id: ID) => number;
  mutation: (id: ID) => Promise<void>;
  onError?: (error: unknown) => void;
  onSuccess?: () => void;
}) {
  return useOptimisticMutation({
    table: options.table,
    snapshot: () => [...options.items.value],
    optimisticUpdate: (id: ID) => {
      const index = options.findFn(id);
      if (index !== -1) {
        options.items.value = options.items.value.filter((_, i) => i !== index);
      }
    },
    mutation: options.mutation,
    rollback: (snapshot) => {
      options.items.value = snapshot ?? [];
    },
    onError: (error) => {
      if (options.onError) {
        options.onError(error);
      }
    },
    onSuccess: () => {
      if (options.onSuccess) {
        options.onSuccess();
      }
    },
  });
}
