import { sql } from "kysely";
import type { MessengerDb } from "./client";

const ensured = new WeakSet<object>();

export async function ensureSchema(db: MessengerDb): Promise<void> {
  if (ensured.has(db)) return;

  await db.schema
    .createTable("messenger_channel")
    .ifNotExists()
    .addColumn("id", "integer", (c) => c.primaryKey())
    .addColumn("name", "text", (c) => c.notNull().defaultTo(""))
    .addColumn("uuid", "text")
    .addColumn("channel_type", "text", (c) => c.notNull().defaultTo("channel"))
    .addColumn("public", "text")
    .addColumn("unread_counter", "integer", (c) => c.notNull().defaultTo(0))
    .addColumn("needaction_counter", "integer", (c) => c.notNull().defaultTo(0))
    .addColumn("seen_message_id", "integer")
    .addColumn("last_message_id", "integer")
    .addColumn("last_message_date", "text")
    .addColumn("last_message_preview", "text")
    .addColumn("members", "text", (c) => c.notNull().defaultTo("[]"))
    .addColumn("seen_partners_info", "text", (c) => c.notNull().defaultTo("[]"))
    .addColumn("direct_partner_id", "integer")
    .addColumn("direct_partner_image", "text")
    .addColumn("is_typing", "text")
    .addColumn("updated_at", "text", (c) => c.notNull().defaultTo(""))
    .execute();

  await db.schema
    .createTable("messenger_message")
    .ifNotExists()
    .addColumn("id", "integer", (c) => c.primaryKey())
    .addColumn("channel_id", "integer", (c) => c.notNull())
    .addColumn("body", "text", (c) => c.notNull().defaultTo(""))
    .addColumn("date", "text")
    .addColumn("author_id", "integer")
    .addColumn("author_name", "text")
    .addColumn("message_type", "text")
    .addColumn("status", "text")
    .addColumn("temp_id", "text")
    .addColumn("attachments", "text", (c) => c.notNull().defaultTo("[]"))
    .addColumn("updated_at", "text", (c) => c.notNull().defaultTo(""))
    .execute();

  await db.schema
    .createTable("messenger_member")
    .ifNotExists()
    .addColumn("id", "integer", (c) => c.primaryKey())
    .addColumn("name", "text", (c) => c.notNull().defaultTo(""))
    .addColumn("im_status", "text")
    .addColumn("phone", "text")
    .addColumn("mobile", "text")
    .addColumn("image_url", "text")
    .addColumn("can_message", "integer", (c) => c.notNull().defaultTo(0))
    .addColumn("updated_at", "text", (c) => c.notNull().defaultTo(""))
    .execute();

  await db.schema
    .createIndex("idx_messenger_channel_last_date")
    .ifNotExists()
    .on("messenger_channel")
    .column("last_message_date")
    .execute();

  await db.schema
    .createIndex("idx_messenger_channel_type")
    .ifNotExists()
    .on("messenger_channel")
    .column("channel_type")
    .execute();

  await db.schema
    .createIndex("idx_messenger_channel_unread")
    .ifNotExists()
    .on("messenger_channel")
    .column("unread_counter")
    .execute();

  await db.schema
    .createIndex("idx_messenger_message_channel")
    .ifNotExists()
    .on("messenger_message")
    .columns(["channel_id", "date"])
    .execute();

  await db.schema
    .createIndex("idx_messenger_member_can_message")
    .ifNotExists()
    .on("messenger_member")
    .column("can_message")
    .execute();

  await sql`
    CREATE VIEW IF NOT EXISTS messenger_channel_list_v AS
    SELECT
      id,
      name,
      channel_type,
      unread_counter,
      last_message_date,
      json_extract(last_message_preview, '$.body') AS last_message_body,
      json_extract(last_message_preview, '$.author') AS last_message_author,
      direct_partner_image AS avatar_url,
      is_typing
    FROM messenger_channel
  `.execute(db);

  ensured.add(db);
}
