import type { MessengerDb } from "../db/client";
import type { ChangeBus } from "../events/changeBus";
import { createChannelRepository, type ChannelRepository } from "./channelRepository";
import { createMemberRepository, type MemberRepository } from "./memberRepository";
import { createMessageRepository, type MessageRepository } from "./messageRepository";

export interface MessengerRepositories {
  channels: ChannelRepository;
  messages: MessageRepository;
  members: MemberRepository;
}

export function createRepositories(db: MessengerDb, bus: ChangeBus): MessengerRepositories {
  return {
    channels: createChannelRepository(db, bus),
    messages: createMessageRepository(db, bus),
    members: createMemberRepository(db, bus),
  };
}

export type { ChannelRepository, MemberRepository, MessageRepository };
export type { ChannelListQuery } from "./channelRepository";
export type { StoredMessage } from "./messageRepository";
