/**
 * Fetch Step (Step 2)
 *
 * Download records from server and apply to local database.
 */

import type { SyncableRecord } from "../types";
import { getSyncTransport } from "../SyncTransport";
import { getTableConfig, getLocalTableName } from "../utils/syncHelpers";
import { parseRecordFromSync } from "../utils/transform";
import { dbService } from "@/shared/database";
import type { Database } from "@/shared/database";
import { emitTableChange } from "@/shared/database";

/**
 * Apply fetched records to local database.
 * Inserts new records and updates existing ones.
 */
async function applyRecords<T extends SyncableRecord>(
  table: string,
  records: T[],
  createRuids: string[],
  updateRuids: string[],
): Promise<{ created: number; updated: number }> {
  if (records.length === 0) {
    return { created: 0, updated: 0 };
  }

  const db = dbService.getDb();
  const localTable = getLocalTableName(table) as keyof Database;
  let created = 0;
  let updated = 0;

  await db.transaction().execute(async (trx) => {
    // We treat all records as potential inserts with an UPSERT (ON CONFLICT UPDATE)
    // This allows SQLite to handle the create vs update logic in a single bridge call.
    const syncRecords = records.map((r) => ({
      ...r,
      _sync_status: "synced" as const,
    }));

    if (syncRecords.length > 0) {
      const chunkSize = 500;
      for (let i = 0; i < syncRecords.length; i += chunkSize) {
        const chunk = syncRecords.slice(i, i + chunkSize);

        // Dynamically build the update set for all columns except _ruid and id
        const firstRecord = chunk[0] ?? {};
        const columnsToUpdate = Object.keys(firstRecord).filter((k) => k !== "_ruid" && k !== "id");

        await trx
          .insertInto(localTable)
          .values(chunk as any)
          .onConflict((oc) =>
            oc.column("_ruid").doUpdateSet((eb) => {
              const updateSet: any = {};
              for (const col of columnsToUpdate) {
                updateSet[col] = eb.ref(`excluded.${col}` as any);
              }
              return updateSet;
            }),
          )
          .execute();
      }

      // Update counters for reporting
      created = records.filter((r) => createRuids.includes(r._ruid)).length;
      updated = records.filter((r) => updateRuids.includes(r._ruid)).length;
    }
  });

  return { created, updated };
}

export interface FetchStepResult {
  /** Number of records created locally */
  created: number;

  /** Number of records updated locally */
  updated: number;

  /** Total records processed */
  total: number;
}

/**
 * Execute the fetch step for a table.
 *
 * @param table - Table name
 * @param toCreate - RUIDs of records to create locally
 * @param toUpdate - RUIDs of records to update locally
 * @returns Stats about applied changes
 */
export async function executeFetchStep<T extends SyncableRecord = SyncableRecord>(
  table: string,
  toCreate: string[],
  toUpdate: string[],
): Promise<FetchStepResult> {
  const allRuids = [...toCreate, ...toUpdate];

  if (allRuids.length === 0) {
    return { created: 0, updated: 0, total: 0 };
  }

  const transport = getSyncTransport();
  const config = getTableConfig(table);

  if (!config) {
    throw new Error(`No config found for table ${table}`);
  }

  // Fetch records from server
  const remoteRecords = await transport.fetch<Record<string, any>>(table, allRuids);

  // Transform records for Local DB
  const records: T[] = (await Promise.all(
    remoteRecords.map((r) => parseRecordFromSync(r, config)),
  )) as T[];

  // Apply to local database
  const result = await applyRecords(table, records, toCreate, toUpdate);

  // Emit change event for reactive layer
  if (result.created > 0 || result.updated > 0) {
    emitTableChange(getLocalTableName(table), "bulk");
  }

  return {
    ...result,
    total: records.length,
  };
}
