/**
 * Server Store
 *
 * Manages server configuration (base URL) with secure persistence via Capacitor Preferences.
 * User can configure multiple servers and select the active one.
 */

import { Preferences } from "@capacitor/preferences";

export interface Server {
  id: string;
  name: string;
  address: string;
  database?: string;
}

const STORAGE_KEY = "server-state";

export const useServerStore = defineStore("server", () => {
  const servers = ref<Server[]>([]);
  const currentServerId = ref<string | null>(null);
  const isLoading = ref(true);

  const currentServer = computed(() => {
    if (!currentServerId.value) return null;
    return servers.value.find((s) => s.id === currentServerId.value) ?? null;
  });

  const baseUrl = computed(() => currentServer.value?.address ?? null);

  async function init() {
    isLoading.value = true;
    try {
      const { value } = await Preferences.get({ key: STORAGE_KEY });
      if (value) {
        const state = JSON.parse(value);
        servers.value = state.servers ?? [];
        currentServerId.value = state.currentServerId ?? null;
      }
    } catch (e) {
      console.error("[ServerStore] Failed to load state", e);
    } finally {
      isLoading.value = false;
    }
  }

  async function persist() {
    await Preferences.set({
      key: STORAGE_KEY,
      value: JSON.stringify({
        servers: servers.value,
        currentServerId: currentServerId.value,
      }),
    });
  }

  async function addServer(server: Omit<Server, "id">) {
    const newServer: Server = { ...server, id: crypto.randomUUID() };
    servers.value.push(newServer);
    currentServerId.value = newServer.id;
    await persist();
    return newServer;
  }

  async function updateServer(id: string, updates: Partial<Omit<Server, "id">>) {
    const index = servers.value.findIndex((s) => s.id === id);
    if (index !== -1) {
      servers.value[index] = { ...servers.value[index]!, ...updates };
      await persist();
    }
  }

  async function removeServer(id: string) {
    servers.value = servers.value.filter((s) => s.id !== id);
    if (currentServerId.value === id) {
      currentServerId.value = servers.value[0]?.id ?? null;
    }
    await persist();
  }

  async function selectServer(id: string) {
    if (servers.value.some((s) => s.id === id)) {
      currentServerId.value = id;
      await persist();
    }
  }

  return {
    // State
    servers,
    currentServerId,
    currentServer,
    baseUrl,
    isLoading,

    // Actions
    init,
    addServer,
    updateServer,
    removeServer,
    selectServer,
  };
});
