export type MessengerTable = "messenger_channel" | "messenger_message" | "messenger_member";

export type ChangeListener = (table: MessengerTable) => void;

export interface ChangeBus {
  emit(table: MessengerTable): void;
  on(listener: ChangeListener): () => void;
}

export function createChangeBus(): ChangeBus {
  const listeners = new Set<ChangeListener>();

  return {
    emit(table) {
      for (const listener of listeners) listener(table);
    },
    on(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
