import type { MessengerRepositories } from "../repositories";
import type { MessengerTransport } from "../transport";
import type { AppVisibility, IncomingMessageNotifier } from "../notifications/types";
import type {
  Message,
  PollEnvelope,
  PollMessage,
  PollSeenEvent,
  PollTypingEvent,
  RemoteChannel,
} from "../types";

export interface PollRouterContext {
  currentPartnerId: number | null;
  openChannelId: number | null;
  visibility: AppVisibility;
}

export interface PollRouterDeps {
  repos: MessengerRepositories;
  transport: MessengerTransport;
  getContext: () => PollRouterContext;
  notify?: IncomingMessageNotifier;
}

export interface PollRouter {
  route(envelopes: PollEnvelope[]): Promise<void>;
}

function isMessage(message: PollMessage): message is Message {
  return "body" in message;
}

function isNewChannel(message: PollMessage): message is RemoteChannel {
  return "channel_type" in message;
}

function isTyping(message: PollMessage): message is PollTypingEvent {
  return "info" in message && message.info === "typing_status";
}

export function createPollRouter(deps: PollRouterDeps): PollRouter {
  const { repos, transport, getContext, notify } = deps;

  async function handleMessage(channelId: number, message: Message) {
    const ctx = getContext();
    const isMine =
      ctx.currentPartnerId != null && message.author_id?.[0] === ctx.currentPartnerId;
    const isChannelOpen = ctx.openChannelId === channelId;

    await repos.messages.upsertMessages(channelId, [message]);
    await repos.channels.applyNewMessage(channelId, message, !isMine && !isChannelOpen);

    if (!isMine && notify) {
      const channelName = await repos.channels.getName(channelId);
      notify({
        channelId,
        channelName,
        message,
        isMine,
        isChannelOpen,
        visibility: ctx.visibility,
      });
    }
  }

  async function handleNewChannel(channel: RemoteChannel) {
    await repos.channels.upsertChannels([channel]);
    try {
      const previews = await transport.channelPreview([channel.id]);
      const preview = previews.find((entry) => entry.id === channel.id);
      if (preview) {
        await repos.channels.upsertChannels([{ ...channel, channelPreview: preview }]);
      }
    } catch {
      /* preview is best-effort */
    }
  }

  return {
    async route(envelopes) {
      for (const envelope of envelopes) {
        const channelId = envelope.channel[2];
        const message = envelope.message;

        if (isMessage(message)) {
          await handleMessage(channelId, message);
        } else if (isNewChannel(message)) {
          await handleNewChannel(message);
        } else if (isTyping(message)) {
          await repos.channels.applyTyping(channelId, message);
        } else {
          await repos.channels.applySeen(channelId, message as PollSeenEvent);
        }
      }
    },
  };
}
