import { readonly, ref, watch, type DeepReadonly, type Ref } from "vue";
import type { ChannelListItem, ChannelTag, MessengerClient } from "../src";

let client: MessengerClient | null = null;
let unsubscribe: (() => void) | null = null;
let reloadTimer: ReturnType<typeof setTimeout> | null = null;
let watchersStarted = false;

const channels = ref<ChannelListItem[]>([]);
const searchQuery = ref("");
const chatTag = ref<ChannelTag>("all");
const unreadCount = ref(0);
const loading = ref(false);
const openChannelId = ref<number | null>(null);

async function reload() {
  if (!client) return;
  loading.value = true;
  try {
    channels.value = await client.repositories.channels.listChannels({
      tag: chatTag.value,
      search: searchQuery.value,
    });
    unreadCount.value = await client.getUnreadTotal();
  } finally {
    loading.value = false;
  }
}

function scheduleReload(delay: number) {
  if (reloadTimer) clearTimeout(reloadTimer);
  reloadTimer = setTimeout(() => void reload(), delay);
}

function startWatchers() {
  if (watchersStarted) return;
  watchersStarted = true;
  watch([searchQuery, chatTag], () => scheduleReload(200));
}

export interface MessengerStore {
  channels: DeepReadonly<Ref<ChannelListItem[]>>;
  searchQuery: Ref<string>;
  chatTag: Ref<ChannelTag>;
  unreadCount: DeepReadonly<Ref<number>>;
  loading: DeepReadonly<Ref<boolean>>;
  openChannelId: DeepReadonly<Ref<number | null>>;
  bindClient(next: MessengerClient): void;
  getClient(): MessengerClient | null;
  reload(): Promise<void>;
  setOpenChannel(channelId: number | null): void;
  markChannelRead(channelId: number): Promise<void>;
}

export function useMessengerStore(): MessengerStore {
  return {
    channels: readonly(channels),
    searchQuery,
    chatTag,
    unreadCount: readonly(unreadCount),
    loading: readonly(loading),
    openChannelId: readonly(openChannelId),

    bindClient(next) {
      client = next;
      unsubscribe?.();
      unsubscribe = next.changeBus.on(() => scheduleReload(120));
      startWatchers();
      void reload();
    },

    getClient() {
      return client;
    },

    reload,

    setOpenChannel(channelId) {
      openChannelId.value = channelId;
    },

    async markChannelRead(channelId) {
      if (!client) return;
      await client.repositories.channels.markChannelRead(channelId);
    },
  };
}
