/**
 * Reactive Kysely wrapper that emits change events.
 *
 * This module wraps the standard Kysely instance to automatically
 * emit table change events on INSERT, UPDATE, DELETE operations.
 * Perfect for building reactive UIs with optimistic updates.
 */

import { type Kysely } from "kysely";
import type { Database } from "@/shared/database/global.schema";
import { emitTableChange } from "./dbEvents";
import type { ChangeType } from "./types";

import { dbService } from "@/shared/database/DatabaseService";

/**
 * Synchronous getter that assumes dbService is already loaded.
 * This is safe because rdb is only used after dbService.init() is called.
 */
function getDbSync(): Kysely<Database> {
  return dbService.getDb();
}

function wrapExecutor<T>(
  executor: () => Promise<T>,
  table: string,
  changeType: ChangeType,
  onExecuted: (table: string, changeType: ChangeType, result: T) => void,
): () => Promise<T> {
  return async () => {
    const result = await executor();

    onExecuted(table, changeType, result);

    return result;
  };
}

function wrapBuilder(
  builder: any,
  table: string,
  changeType: ChangeType,
  onExecuted: (table: string, changeType: ChangeType, result: unknown) => void,
): any {
  return new Proxy(builder, {
    get(target, prop) {
      const value = target[prop];

      if (typeof value !== "function") {
        return value;
      }

      if (prop === "execute" || prop === "executeTakeFirst" || prop === "executeTakeFirstOrThrow") {
        return wrapExecutor(value.bind(target), table, changeType, onExecuted);
      }

      return (...args: any[]) => {
        const result = value.apply(target, args);

        if (result && typeof result.execute === "function" && result !== target) {
          return wrapBuilder(result, table, changeType, onExecuted);
        }

        return result;
      };
    },
  });
}

function emitMutationEvent(table: string, changeType: ChangeType, result: unknown): void {
  emitTableChange(table, changeType, {
    affectedRows: Array.isArray(result) ? result.length : 1,
  });
}

function createMutationProxy(
  db: Kysely<Database>,
  onExecuted: (table: string, changeType: ChangeType, result: unknown) => void,
): Kysely<Database> {
  return new Proxy(db, {
    get(target, prop) {
      const value = (target as any)[prop];

      if (prop === "insertInto" || prop === "updateTable" || prop === "deleteFrom") {
        const changeTypeMap: Record<string, ChangeType> = {
          insertInto: "insert",
          updateTable: "update",
          deleteFrom: "delete",
        };

        return (...args: any[]) => {
          const table = args[0] as string;
          const builder = value.apply(target, args);
          const changeType = changeTypeMap[prop as string] as ChangeType;

          return wrapBuilder(builder, table, changeType, onExecuted);
        };
      }

      if (typeof value === "function") {
        return value.bind(target);
      }

      return value;
    },
  }) as Kysely<Database>;
}

function wrapTransactionBuilder(txBuilder: any): any {
  return new Proxy(txBuilder, {
    get(target, prop) {
      const value = target[prop];

      if (prop === "execute" && typeof value === "function") {
        return async (callback: any) => {
          const touchedTables = new Set<string>();
          const result = await value.call(target, (trx: Kysely<Database>) =>
            callback(
              createMutationProxy(trx, (table) => {
                touchedTables.add(table);
              }),
            ),
          );

          for (const table of touchedTables) {
            emitTableChange(table, "bulk");
          }

          return result;
        };
      }

      if (typeof value === "function") {
        return (...args: any[]) => {
          const result = value.apply(target, args);

          if (result && typeof result.execute === "function") {
            return wrapTransactionBuilder(result);
          }

          return result;
        };
      }

      return value;
    },
  });
}

/**
 * Reactive Kysely database instance.
 *
 * Drop-in replacement for `db` that emits change events on mutations.
 * All queries (SELECT, INSERT, UPDATE, DELETE) work exactly the same,
 * but mutations trigger reactive updates.
 *
 * @example
 * ```ts
 * // This will emit a 'customers:insert' event
 * await rdb.insertInto('customers')
 *   .values({ customer_name: 'Alice', country_id: 1 })
 *   .execute();
 *
 * // This will emit a 'customers:update' event
 * await rdb.updateTable('customers')
 *   .set({ customer_name: 'Bob' })
 *   .where('customer_id', '=', 1)
 *   .execute();
 *
 * // This will emit a 'customers:delete' event
 * await rdb.deleteFrom('customers')
 *   .where('customer_id', '=', 1)
 *   .execute();
 * ```
 */
export const rdb = new Proxy({} as Kysely<Database>, {
  get(target, prop) {
    const db = getDbSync();
    const value = (db as any)[prop];

    if (prop === "insertInto" || prop === "updateTable" || prop === "deleteFrom") {
      const changeTypeMap: Record<string, ChangeType> = {
        insertInto: "insert",
        updateTable: "update",
        deleteFrom: "delete",
      };

      return (...args: any[]) => {
        const table = args[0] as string;
        const builder = value.apply(db, args);
        const changeType = changeTypeMap[prop as string] as ChangeType;

        return wrapBuilder(builder, table, changeType, emitMutationEvent);
      };
    }

    if (prop === "transaction") {
      return () => {
        const txBuilder = value.apply(db, []);
        return wrapTransactionBuilder(txBuilder);
      };
    }

    if (typeof value === "function") {
      return value.bind(db);
    }

    return value;
  },
}) as Kysely<Database>;

/**
 * Helper: Execute a raw SQL mutation and emit a change event
 *
 * Use this when you need to use `getRawConnection()` for native SQLite features
 * but still want reactive updates.
 *
 * @example
 * ```ts
 * await executeWithEvent('customers', 'insert', async () => {
 *   const conn = await getRawConnection();
 *   return await conn.executeSet([{
 *     statement: 'INSERT INTO customers (customer_name) VALUES (?)',
 *     values: [['Alice'], ['Bob']]
 *   }]);
 * });
 * ```
 */
export async function executeWithEvent<T>(
  table: string,
  changeType: ChangeType,
  executor: () => Promise<T>,
): Promise<T> {
  const result = await executor();
  emitTableChange(table, changeType);
  return result;
}
