import type { MessengerTransport } from "../transport";
import type { NetworkMonitor } from "./network";
import type { PollRouter } from "./pollEventRouter";

export interface PollOrchestratorDeps {
  transport: MessengerTransport;
  router: PollRouter;
  network: NetworkMonitor;
  onError?: (error: unknown) => void;
  retryDelayMs?: number;
}

export interface PollOrchestrator {
  start(): Promise<void>;
  stop(): void;
  isRunning(): boolean;
}

const DEFAULT_RETRY_MS = 5000;

export function createPollOrchestrator(deps: PollOrchestratorDeps): PollOrchestrator {
  const { transport, router, network } = deps;
  const retryDelay = deps.retryDelayMs ?? DEFAULT_RETRY_MS;

  let running = false;
  let polling = false;
  let online = true;
  let lastPollId = 0;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let controller: AbortController | null = null;
  let unsubscribeNetwork: (() => void) | null = null;

  function clearTimer() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext(delay: number) {
    clearTimer();
    if (!running) return;
    timer = setTimeout(() => {
      void poll();
    }, delay);
  }

  async function poll() {
    if (!running || polling || !online) return;
    polling = true;
    try {
      const envelopes = await transport.longPoll(lastPollId, { signal: controller?.signal });
      if (envelopes.length > 0) {
        const latest = envelopes[envelopes.length - 1];
        if (latest) lastPollId = latest.id;
        await router.route(envelopes);
      }
      polling = false;
      scheduleNext(0);
    } catch (error) {
      polling = false;
      if (!running) return;
      deps.onError?.(error);
      scheduleNext(retryDelay);
    }
  }

  return {
    async start() {
      if (running) return;
      running = true;
      controller = new AbortController();
      online = await network.isOnline();
      unsubscribeNetwork = network.onChange((next) => {
        const wasOffline = !online;
        online = next;
        if (next && wasOffline) void poll();
      });
      void poll();
    },

    stop() {
      running = false;
      clearTimer();
      controller?.abort();
      controller = null;
      unsubscribeNetwork?.();
      unsubscribeNetwork = null;
      polling = false;
    },

    isRunning() {
      return running;
    },
  };
}
