import type { ChannelPreview } from "../types";
import type { MessengerEndpoints } from "./endpoints";
import type { MessengerHttpClient } from "./http";

export function fetchChannelPreview(
  http: MessengerHttpClient,
  endpoints: MessengerEndpoints,
  channelIds: number[],
): Promise<ChannelPreview[]> {
  return http.post<ChannelPreview[]>(
    endpoints.callKw(endpoints.channelModel, "channel_fetch_preview"),
    {
      model: endpoints.channelModel,
      method: "channel_fetch_preview",
      args: [channelIds],
      kwargs: {},
    },
  );
}
