/**
 * Concurrency Control Utilities
 *
 * Provides concurrency limiting for parallel sync operations.
 * Prevents overwhelming the server/client with too many simultaneous requests.
 */

export interface ConcurrencyLimiterOptions {
  /**
   * Maximum number of concurrent operations.
   * Default: 4 (good balance for mobile networks)
   */
  concurrency?: number;
}

/**
 * Limits concurrent promise executions.
 *
 * @example
 * const limiter = createConcurrencyLimiter({ concurrency: 4 });
 *
 * const tasks = tables.map(table =>
 *   limiter(() => syncTable(table))
 * );
 *
 * await Promise.all(tasks);
 */
export function createConcurrencyLimiter(options: ConcurrencyLimiterOptions = {}) {
  const { concurrency = 4 } = options;
  const queue: Array<() => void> = [];
  let activeCount = 0;

  const next = () => {
    if (queue.length === 0) return;
    if (activeCount >= concurrency) return;

    const resolve = queue.shift();
    if (resolve) {
      activeCount++;
      resolve();
    }
  };

  const run = async <T>(fn: () => Promise<T>): Promise<T> => {
    // Wait for slot
    if (activeCount >= concurrency) {
      await new Promise<void>((resolve) => queue.push(resolve));
    }

    activeCount++;

    try {
      return await fn();
    } finally {
      activeCount--;
      next();
    }
  };

  return run;
}

/**
 * Chunk array into smaller batches for parallel processing.
 *
 * @example
 * const tables = [...17 tables];
 * const batches = chunkArray(tables, 4); // [[4 tables], [4 tables], [4 tables], [4 tables], [1 table]]
 *
 * for (const batch of batches) {
 *   await Promise.all(batch.map(syncTable));
 * }
 */
export function chunkArray<T>(array: T[], chunkSize: number): T[][] {
  const chunks: T[][] = [];

  for (let i = 0; i < array.length; i += chunkSize) {
    chunks.push(array.slice(i, i + chunkSize));
  }

  return chunks;
}

/**
 * Parallel map with concurrency limit.
 *
 * @example
 * const results = await parallelMap(
 *   tables,
 *   async (table) => await syncTable(table),
 *   { concurrency: 4 }
 * );
 */
export async function parallelMap<T, R>(
  items: T[],
  mapper: (item: T, index: number) => Promise<R>,
  options: ConcurrencyLimiterOptions = {},
): Promise<R[]> {
  const limiter = createConcurrencyLimiter(options);
  const promises = items.map((item, index) => limiter(() => mapper(item, index)));
  return Promise.all(promises);
}

/**
 * Parallel map with concurrency limit, but catches errors individually.
 * Returns PromiseSettledResult for each item.
 *
 * @example
 * const results = await parallelMapSettled(
 *   tables,
 *   async (table) => await syncTable(table),
 *   { concurrency: 4 }
 * );
 *
 * results.forEach((result, index) => {
 *   if (result.status === 'fulfilled') {
 *     console.log(`Table ${index} synced successfully`);
 *   } else {
 *     console.error(`Table ${index} failed:`, result.reason);
 *   }
 * });
 */
export async function parallelMapSettled<T, R>(
  items: T[],
  mapper: (item: T, index: number) => Promise<R>,
  options: ConcurrencyLimiterOptions = {},
): Promise<PromiseSettledResult<R>[]> {
  const limiter = createConcurrencyLimiter(options);
  const promises = items.map((item, index) => limiter(() => mapper(item, index)));
  return Promise.allSettled(promises);
}
