import { sql } from "kysely";
import type { MessengerDb } from "../db/client";
import type {
  ChannelRowUpdate,
  MessengerChannelListView,
  NewChannelRow,
} from "../db/schema";
import type { ChangeBus } from "../events/changeBus";
import type {
  ChannelTag,
  ChannelListItem,
  ChannelType,
  Member,
  PollSeenEvent,
  PollTypingEvent,
  RemoteChannel,
} from "../types";
import type { Message } from "../types";
import { nowIso } from "../utils/time";
import { toPreviewText } from "../utils/html";

export interface ChannelListQuery {
  tag?: ChannelTag;
  search?: string;
}

export interface ChannelRepository {
  upsertChannels(channels: RemoteChannel[]): Promise<void>;
  listChannels(query?: ChannelListQuery): Promise<ChannelListItem[]>;
  applyNewMessage(channelId: number, message: Message, countUnread: boolean): Promise<void>;
  applySeen(channelId: number, event: PollSeenEvent): Promise<void>;
  applyTyping(channelId: number, event: PollTypingEvent): Promise<void>;
  markChannelRead(channelId: number): Promise<void>;
  getUnreadTotal(): Promise<number>;
  getName(channelId: number): Promise<string | null>;
}

function buildPreview(message: Message): string {
  return JSON.stringify({
    id: message.id,
    body: toPreviewText(message.body),
    author: message.author_id?.[1] ?? "",
    date: message.date,
  });
}

function toChannelRow(channel: RemoteChannel, now: string): NewChannelRow {
  const last = channel.channelPreview?.last_message;
  const direct = channel.direct_partner?.[0];

  return {
    id: channel.id,
    name: channel.name,
    uuid: channel.uuid ?? null,
    channel_type: channel.channel_type,
    public: channel.public ?? null,
    unread_counter: channel.message_unread_counter ?? 0,
    needaction_counter: channel.message_needaction_counter ?? 0,
    seen_message_id: channel.seen_message_id ?? null,
    last_message_id: last?.id ?? null,
    last_message_date: last?.date ?? null,
    last_message_preview: last ? buildPreview(last) : null,
    members: JSON.stringify(channel.members ?? []),
    seen_partners_info: JSON.stringify(channel.seen_partners_info ?? []),
    direct_partner_id: direct?.id ?? null,
    direct_partner_image: direct?.image_url ?? null,
    is_typing: null,
    updated_at: now,
  };
}

function toListItem(row: MessengerChannelListView): ChannelListItem {
  let isTyping = false;
  let typingName: string | null = null;

  if (row.is_typing) {
    try {
      const parsed = JSON.parse(row.is_typing) as { status?: boolean; partnerName?: string };
      isTyping = Boolean(parsed.status);
      typingName = parsed.partnerName ?? null;
    } catch {
      isTyping = false;
    }
  }

  return {
    id: row.id,
    name: row.name,
    channelType: row.channel_type as ChannelType,
    unreadCount: row.unread_counter,
    lastMessageBody: row.last_message_body,
    lastMessageAuthor: row.last_message_author,
    lastMessageDate: row.last_message_date,
    avatarUrl: row.avatar_url,
    isTyping,
    typingName,
  };
}

export function createChannelRepository(db: MessengerDb, bus: ChangeBus): ChannelRepository {
  return {
    async upsertChannels(channels) {
      if (!channels.length) return;
      const now = nowIso();
      const rows = channels.map((channel) => toChannelRow(channel, now));

      await db
        .insertInto("messenger_channel")
        .values(rows)
        .onConflict((oc) =>
          oc.column("id").doUpdateSet((eb) => ({
            name: eb.ref("excluded.name"),
            uuid: eb.ref("excluded.uuid"),
            channel_type: eb.ref("excluded.channel_type"),
            public: eb.ref("excluded.public"),
            unread_counter: eb.ref("excluded.unread_counter"),
            needaction_counter: eb.ref("excluded.needaction_counter"),
            seen_message_id: eb.ref("excluded.seen_message_id"),
            last_message_id: eb.ref("excluded.last_message_id"),
            last_message_date: eb.ref("excluded.last_message_date"),
            last_message_preview: eb.ref("excluded.last_message_preview"),
            members: eb.ref("excluded.members"),
            seen_partners_info: eb.ref("excluded.seen_partners_info"),
            direct_partner_id: eb.ref("excluded.direct_partner_id"),
            direct_partner_image: eb.ref("excluded.direct_partner_image"),
            updated_at: eb.ref("excluded.updated_at"),
          })),
        )
        .execute();

      bus.emit("messenger_channel");
    },

    async listChannels(query = {}) {
      let q = db.selectFrom("messenger_channel_list_v").selectAll();

      if (query.tag === "unread") q = q.where("unread_counter", ">", 0);
      if (query.tag === "group") q = q.where("channel_type", "!=", "chat");

      const search = query.search?.trim().toLowerCase();
      if (search) {
        for (const term of search.split(/\s+/)) {
          q = q.where("name", "like", `%${term}%`);
        }
      }

      const rows = await q.orderBy("last_message_date", "desc").orderBy("name", "asc").execute();
      return rows.map(toListItem);
    },

    async applyNewMessage(channelId, message, countUnread) {
      const update: ChannelRowUpdate = {
        last_message_id: message.id,
        last_message_date: message.date,
        last_message_preview: buildPreview(message),
        updated_at: nowIso(),
      };

      await db
        .updateTable("messenger_channel")
        .set(update)
        .where("id", "=", channelId)
        .execute();

      if (countUnread) {
        await db
          .updateTable("messenger_channel")
          .set({ unread_counter: sql`unread_counter + 1` })
          .where("id", "=", channelId)
          .execute();
      }

      bus.emit("messenger_channel");
    },

    async applySeen(channelId, event) {
      const row = await db
        .selectFrom("messenger_channel")
        .select(["seen_partners_info"])
        .where("id", "=", channelId)
        .executeTakeFirst();
      if (!row) return;

      const seen: Array<{
        partner_id: number;
        fetched_message_id: number;
        seen_message_id: number;
      }> = JSON.parse(row.seen_partners_info || "[]");

      const existing = seen.find((entry) => entry.partner_id === event.partner_id);
      if (existing) {
        if (event.info === "channel_seen") existing.seen_message_id = event.last_message_id;
        else existing.fetched_message_id = event.last_message_id;
      } else {
        seen.push({
          partner_id: event.partner_id,
          fetched_message_id: event.info === "channel_fetched" ? event.last_message_id : 0,
          seen_message_id: event.info === "channel_seen" ? event.last_message_id : 0,
        });
      }

      const update: ChannelRowUpdate = {
        seen_partners_info: JSON.stringify(seen),
        updated_at: nowIso(),
      };
      if (event.info === "channel_seen") update.seen_message_id = event.last_message_id;

      await db
        .updateTable("messenger_channel")
        .set(update)
        .where("id", "=", channelId)
        .execute();
      bus.emit("messenger_channel");
    },

    async applyTyping(channelId, event) {
      const row = await db
        .selectFrom("messenger_channel")
        .select(["members"])
        .where("id", "=", channelId)
        .executeTakeFirst();
      if (!row) return;

      const members: Member[] = JSON.parse(row.members || "[]");
      const partner = members.find((member) => member.id === event.partner_id);

      const update: ChannelRowUpdate = {
        is_typing: JSON.stringify({
          status: event.is_typing,
          partnerId: event.partner_id,
          partnerName: partner?.name ?? null,
        }),
        updated_at: nowIso(),
      };

      await db
        .updateTable("messenger_channel")
        .set(update)
        .where("id", "=", channelId)
        .execute();
      bus.emit("messenger_channel");
    },

    async markChannelRead(channelId) {
      await db
        .updateTable("messenger_channel")
        .set({ unread_counter: 0, updated_at: nowIso() })
        .where("id", "=", channelId)
        .execute();
      bus.emit("messenger_channel");
    },

    async getUnreadTotal() {
      const row = await db
        .selectFrom("messenger_channel")
        .select((eb) => eb.fn.sum<number>("unread_counter").as("total"))
        .executeTakeFirst();
      return Number(row?.total ?? 0);
    },

    async getName(channelId) {
      const row = await db
        .selectFrom("messenger_channel")
        .select(["name"])
        .where("id", "=", channelId)
        .executeTakeFirst();
      return row?.name ?? null;
    },
  };
}
