import type { Kysely } from "kysely";
import { asMessengerDb } from "./db/client";
import { ensureSchema } from "./db/ensureSchema";
import { createChangeBus, type ChangeBus } from "./events/changeBus";
import { createRepositories, type MessengerRepositories } from "./repositories";
import { createTransport, type MessengerTransport } from "./transport";
import type { MessengerEndpoints } from "./transport";
import type { MessengerHttpClient } from "./transport";
import { createPollOrchestrator, createPollRouter, alwaysOnlineMonitor } from "./poll";
import type { NetworkMonitor } from "./poll";
import {
  createNotificationController,
  type NotificationController,
  type NotificationHost,
  type AppVisibility,
} from "./notifications";
import type { Member, MessengerUser } from "./types";

export interface MessengerClientDeps {
  db: Kysely<any>;
  http: MessengerHttpClient;
  currentUser: () => MessengerUser | null;
  endpoints?: Partial<MessengerEndpoints>;
  network?: NetworkMonitor;
  notifications?: NotificationHost;
  getVisibility?: () => AppVisibility;
  getOpenChannelId?: () => number | null;
  onPollError?: (error: unknown) => void;
}

export interface MessengerClient {
  repositories: MessengerRepositories;
  transport: MessengerTransport;
  notifications: NotificationController;
  changeBus: ChangeBus;
  init(): Promise<void>;
  refreshChannels(): Promise<void>;
  loadCanMessagePartners(): Promise<Member[]>;
  startPolling(): Promise<void>;
  stopPolling(): void;
  getUnreadTotal(): Promise<number>;
}

function uniqueMembers(members: Member[]): Member[] {
  const seen = new Map<number, Member>();
  for (const member of members) {
    if (!seen.has(member.id)) seen.set(member.id, member);
  }
  return [...seen.values()];
}

export function createMessengerClient(deps: MessengerClientDeps): MessengerClient {
  const db = asMessengerDb(deps.db);
  const changeBus = createChangeBus();
  const repositories = createRepositories(db, changeBus);
  const transport = createTransport({ http: deps.http, endpoints: deps.endpoints });

  const notifications = createNotificationController({
    host: deps.notifications,
    getUnreadTotal: () => repositories.channels.getUnreadTotal(),
  });

  const router = createPollRouter({
    repos: repositories,
    transport,
    getContext: () => ({
      currentPartnerId: deps.currentUser()?.partnerId ?? null,
      openChannelId: deps.getOpenChannelId?.() ?? null,
      visibility: deps.getVisibility?.() ?? "foreground",
    }),
    notify: notifications.onIncomingMessage,
  });

  const orchestrator = createPollOrchestrator({
    transport,
    router,
    network: deps.network ?? alwaysOnlineMonitor,
    onError: deps.onPollError,
  });

  let schemaReady: Promise<void> | null = null;

  return {
    repositories,
    transport,
    notifications,
    changeBus,

    init() {
      schemaReady ??= ensureSchema(db);
      return schemaReady;
    },

    async refreshChannels() {
      const channels = await transport.loadChannels();
      await repositories.channels.upsertChannels(channels);

      const members = uniqueMembers(channels.flatMap((channel) => channel.members ?? []));
      await repositories.members.upsertMembers(members, false);

      const ids = channels.map((channel) => channel.id);
      if (ids.length > 0) {
        try {
          const previews = await transport.channelPreview(ids);
          const previewById = new Map(previews.map((preview) => [preview.id, preview]));
          const merged = channels
            .filter((channel) => previewById.has(channel.id))
            .map((channel) => ({ ...channel, channelPreview: previewById.get(channel.id) }));
          await repositories.channels.upsertChannels(merged);
        } catch (error) {
          deps.onPollError?.(error);
        }
      }

      await notifications.refreshBadge();
    },

    async loadCanMessagePartners() {
      const partners = await transport.canMessagePartners();
      await repositories.members.upsertMembers(partners, true);
      return partners;
    },

    async startPolling() {
      await orchestrator.start();
    },

    stopPolling() {
      orchestrator.stop();
    },

    getUnreadTotal() {
      return repositories.channels.getUnreadTotal();
    },
  };
}
