import { createMessengerClient, type AppVisibility, type MessengerUser } from "@aybsig/messenger";
import { useMessengerStore } from "@aybsig/messenger/vue";
import { App } from "@capacitor/app";
import { dbService } from "@/shared/database/DatabaseService";
import { useAuthStore } from "@/shared/stores/auth.store";
import { createMessengerHttpClient } from "./messengerHttpClient";
import { createMessengerNetworkMonitor } from "./messengerNetworkMonitor";
import { createMessengerNotificationHost } from "./messengerNotificationHost";

let setupPromise: Promise<void> | null = null;
let visibility: AppVisibility = "foreground";
let visibilityBound = false;

function currentUser(): MessengerUser | null {
  const authUser = useAuthStore().user as { partner_id?: number; name?: string } | null;
  if (!authUser || typeof authUser.partner_id !== "number") return null;
  return { partnerId: authUser.partner_id, name: authUser.name };
}

function bindVisibility() {
  if (visibilityBound) return;
  visibilityBound = true;
  void App.addListener("appStateChange", (state) => {
    visibility = state.isActive ? "foreground" : "background";
  });
}

export function ensureMessengerSetup(): Promise<void> {
  if (setupPromise) return setupPromise;

  const store = useMessengerStore();

  setupPromise = (async () => {
    bindVisibility();

    const client = createMessengerClient({
      db: dbService.getDb(),
      http: createMessengerHttpClient(),
      network: createMessengerNetworkMonitor(),
      notifications: createMessengerNotificationHost(),
      currentUser,
      getVisibility: () => visibility,
      getOpenChannelId: () => store.openChannelId.value,
      onPollError: (error) => console.warn("[messenger] poll error", error),
    });

    await client.init();
    store.bindClient(client);
    await client
      .refreshChannels()
      .catch((error) => console.warn("[messenger] initial refresh failed", error));
    await client.startPolling();
  })();

  return setupPromise;
}
