import type { PollEnvelope } from "../types";
import { BUS_INACTIVITY, type MessengerEndpoints } from "./endpoints";
import type { MessengerHttpClient, MessengerRequestInit } from "./http";

export function fetchLongPoll(
  http: MessengerHttpClient,
  endpoints: MessengerEndpoints,
  last: number,
  init?: MessengerRequestInit,
): Promise<PollEnvelope[]> {
  return http.post<PollEnvelope[]>(
    endpoints.longPoll,
    {
      params: {
        channels: [],
        last,
        options: {
          bus_inactivity: BUS_INACTIVITY,
        },
      },
    },
    init,
  );
}
