import { Capacitor } from "@capacitor/core";
import { Filesystem, Directory } from "@capacitor/filesystem";
import type { SyncTableConfig, SyncableRecord } from "../types";

interface TransformSetGet {
  read: (val: any) => Promise<any> | any;
  write: (val: any) => Promise<any> | any;
}

export type SyncMetaDataTransformer = Record<string, TransformSetGet>;

export function prepareDateTimeUTC(
  date: Date | string | null | undefined,
): string | null | undefined {
  if (!date) return null;
  const d = typeof date === "string" ? new Date(date) : date;
  if (isNaN(d.getTime())) return null;
  return d.toISOString().replace("T", " ").split(".")[0];
}

export function dateFromUTC(strDate: string | null | undefined): string | null {
  if (!strDate) return null;
  const d = new Date(strDate);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

export const dateTransform: TransformSetGet = {
  read: (strDate: string | null) => dateFromUTC(strDate),
  write: (val: any) => prepareDateTimeUTC(val),
};

export const fileTransform: TransformSetGet = {
  read: async (dataUrl: string | null) => {
    if (!dataUrl) return null;

    if (Capacitor.isNativePlatform()) {
      try {
        const matches = dataUrl.match(/^data:([A-Za-z-+/]+);base64,(.+)$/);
        if (!matches || matches.length !== 3) return dataUrl;

        const type = matches[1];
        const rawBase64 = matches[2];
        if (!type || !rawBase64) return dataUrl;

        const ext = type.split("/")[1] || "jpg";
        const filename = `${crypto.randomUUID()}.${ext}`;

        const savedFile = await Filesystem.writeFile({
          path: filename,
          data: rawBase64,
          directory: Directory.Documents,
          recursive: true,
        });
        return savedFile.uri;
      } catch (e) {
        console.error("[fileTransform] Write failed:", e);
        return dataUrl;
      }
    }
    return dataUrl;
  },

  write: async (localPathOrDataUrl: string | null) => {
    if (!localPathOrDataUrl) return null;

    if (Capacitor.isNativePlatform() && !localPathOrDataUrl.startsWith("data:")) {
      try {
        const file = await Filesystem.readFile({ path: localPathOrDataUrl });
        const ext = localPathOrDataUrl.split(".").pop() || "jpg";
        const mimeType = ext === "png" ? "image/png" : "image/jpeg";
        return `data:${mimeType};base64,${file.data}`;
      } catch (e) {
        console.error("[fileTransform] Read failed:", e);
        return null;
      }
    }
    return localPathOrDataUrl;
  },
};

export async function prepareRecordForSync(
  record: SyncableRecord,
  config: SyncTableConfig,
): Promise<Record<string, any>> {
  let remoteRecord: Record<string, any> = {};

  if (config.fields) {
    remoteRecord._ruid = record._ruid;
    remoteRecord._create_date = record._create_date;
    remoteRecord._write_date = record._write_date;
    remoteRecord._delete_date = record._delete_date;

    for (const field of config.fields) {
      if (field in record) {
        remoteRecord[field] = (record as any)[field];
      }
    }
  } else {
    remoteRecord = { ...record };
  }

  for (const key of Object.keys(remoteRecord)) {
    if (key.toLowerCase().includes("date")) {
      const val = remoteRecord[key];
      if (val) {
        remoteRecord[key] = prepareDateTimeUTC(val) ?? val;
      }
    }
  }

  if (config.transforms) {
    for (const key of Object.keys(config.transforms)) {
      if (key in remoteRecord) {
        remoteRecord[key] = await config.transforms[key]?.write(remoteRecord[key]);
      }
    }
  }

  // Final pass: ensure internal objects/arrays are parsed if they were stringified
  for (const key of Object.keys(remoteRecord)) {
    const val = remoteRecord[key];
    if (typeof val === "string" && (val.startsWith("{") || val.startsWith("["))) {
      try {
        remoteRecord[key] = JSON.parse(val);
      } catch (e) {
        // Not a JSON string after all
      }
    }
  }

  return remoteRecord;
}

export async function parseRecordFromSync(
  remoteRecord: Record<string, any>,
  config: SyncTableConfig,
): Promise<SyncableRecord> {
  // Only keep fields defined in the config, plus internal sync fields
  const localRecord: any = {
    _ruid: remoteRecord._ruid,
    _create_date: remoteRecord._create_date,
    _write_date: remoteRecord._write_date,
  };

  if (config.fields) {
    for (const field of config.fields) {
      if (field in remoteRecord) {
        localRecord[field] = remoteRecord[field];
      }
    }
  } else {
    // If no fields defined, copy everything (fallback)
    Object.assign(localRecord, remoteRecord);
  }

  for (const key of Object.keys(localRecord)) {
    if (key.toLowerCase().includes("date")) {
      const val = localRecord[key];
      if (val) {
        localRecord[key] = dateFromUTC(val) ?? val;
      }
    }
  }

  if (config.transforms) {
    for (const key of Object.keys(config.transforms)) {
      if (key in localRecord) {
        localRecord[key] = await config.transforms[key]?.read(localRecord[key]);
      }
    }
  }

  // Ensure all objects/arrays are stringified for SQLite (Final pass)
  for (const key of Object.keys(localRecord)) {
    const val = localRecord[key];
    if (val && typeof val === "object" && !(val instanceof Date)) {
      localRecord[key] = JSON.stringify(val);
    }
  }

  return localRecord;
}
