import { createRepository } from "@/shared/database/repository";
import type { Row } from "@/shared/database/repository";

export const productRepo = createRepository("product_product");
export const productTemplateRepo = createRepository("product_template");
export const productCategoryRepo = createRepository("product_category");
export const productBrandRepo = createRepository("product_brand");

export const productRepositories = {
  product: productRepo,
  template: productTemplateRepo,
  category: productCategoryRepo,
  brand: productBrandRepo,
} as const;

export function listActiveProducts(): Promise<Row<"product_product">[]> {
  return productRepo.list({
    orderBy: { column: "name", direction: "asc" },
  });
}
