import type { NotificationHost } from "@aybsig/messenger";
import { Capacitor } from "@capacitor/core";
import { f7 } from "framework7-vue";
import { notificationService } from "@/shared/services/notifications/notification.service";

export function createMessengerNotificationHost(): NotificationHost {
  return {
    showInApp(notification) {
      f7.toast
        .create({
          text: notification.body ? `${notification.title}: ${notification.body}` : notification.title,
          position: "top",
          closeTimeout: 3500,
        })
        .open();
    },
    async showLocal(notification) {
      if (!Capacitor.isNativePlatform()) return;
      await notificationService.scheduleLocal({
        title: notification.title,
        body: notification.body,
        extra: { channelId: notification.channelId },
      });
    },
  };
}
