import type { MessengerHttpClient } from "@aybsig/messenger";
import { useApiInstance } from "@/shared/composables/utils/useApiInstance";

interface OdooEnvelope<T> {
  result?: T;
  error?: { data?: { message?: string } };
}

function unwrap<T>(payload: OdooEnvelope<T> | T): T {
  const envelope = payload as OdooEnvelope<T>;
  if (envelope && typeof envelope === "object" && "error" in envelope && envelope.error) {
    throw new Error(envelope.error.data?.message ?? "Messenger request failed");
  }
  if (envelope && typeof envelope === "object" && "result" in envelope) {
    return envelope.result as T;
  }
  return payload as T;
}

export function createMessengerHttpClient(): MessengerHttpClient {
  const api = useApiInstance();

  return {
    async post<T>(url: string, body?: unknown, init?: { signal?: AbortSignal }) {
      const response = await api.post(url, body ?? {}, { signal: init?.signal });
      return unwrap<T>(response.data);
    },
    async get<T>(url: string, init?: { signal?: AbortSignal }) {
      const response = await api.get(url, { signal: init?.signal });
      return unwrap<T>(response.data);
    },
  };
}
