import type { MessengerDb } from "../db/client";
import type { NewMemberRow } from "../db/schema";
import type { ChangeBus } from "../events/changeBus";
import type { ImStatus, Member } from "../types";
import { nowIso } from "../utils/time";

export interface MemberRepository {
  upsertMembers(members: Member[], canMessage: boolean): Promise<void>;
  listCanMessage(search?: string): Promise<Member[]>;
  setImStatus(partnerId: number, status: ImStatus): Promise<void>;
}

function toMemberRow(member: Member, canMessage: boolean, now: string): NewMemberRow {
  return {
    id: member.id,
    name: member.name,
    im_status: member.im_status ?? null,
    phone: member.phone ?? null,
    mobile: member.mobile ?? null,
    image_url: member.image_url ?? null,
    can_message: canMessage ? 1 : 0,
    updated_at: now,
  };
}

function toMember(row: {
  id: number;
  name: string;
  im_status: string | null;
  phone: string | null;
  mobile: string | null;
  image_url: string | null;
}): Member {
  return {
    id: row.id,
    name: row.name,
    im_status: (row.im_status as ImStatus) ?? "offline",
    phone: row.phone,
    mobile: row.mobile,
    image_url: row.image_url,
  };
}

export function createMemberRepository(db: MessengerDb, bus: ChangeBus): MemberRepository {
  return {
    async upsertMembers(members, canMessage) {
      if (!members.length) return;
      const now = nowIso();
      const rows = members.map((member) => toMemberRow(member, canMessage, now));

      await db
        .insertInto("messenger_member")
        .values(rows)
        .onConflict((oc) =>
          oc.column("id").doUpdateSet((eb) => ({
            name: eb.ref("excluded.name"),
            im_status: eb.ref("excluded.im_status"),
            phone: eb.ref("excluded.phone"),
            mobile: eb.ref("excluded.mobile"),
            image_url: eb.ref("excluded.image_url"),
            can_message: eb.ref("excluded.can_message"),
            updated_at: eb.ref("excluded.updated_at"),
          })),
        )
        .execute();

      bus.emit("messenger_member");
    },

    async listCanMessage(search) {
      let q = db.selectFrom("messenger_member").selectAll().where("can_message", "=", 1);

      const term = search?.trim().toLowerCase();
      if (term) {
        for (const part of term.split(/\s+/)) {
          q = q.where("name", "like", `%${part}%`);
        }
      }

      const rows = await q.orderBy("name", "asc").execute();
      return rows.map(toMember);
    },

    async setImStatus(partnerId, status) {
      await db
        .updateTable("messenger_member")
        .set({ im_status: status, updated_at: nowIso() })
        .where("id", "=", partnerId)
        .execute();
      bus.emit("messenger_member");
    },
  };
}
