import type { ChannelSlots, InitMessagingResponse, RemoteChannel } from "../types";
import type { MessengerEndpoints } from "./endpoints";
import type { MessengerHttpClient } from "./http";

export function fetchInitMessaging(
  http: MessengerHttpClient,
  endpoints: MessengerEndpoints,
): Promise<InitMessagingResponse> {
  return http.post<InitMessagingResponse>(endpoints.initMessaging, {
    params: {
      context: {
        isMobile: true,
      },
    },
  });
}

export function flattenChannelSlots(slots: ChannelSlots | undefined): RemoteChannel[] {
  if (!slots) return [];
  return [
    ...(slots.channel_channel ?? []),
    ...(slots.channel_direct_message ?? []),
    ...(slots.channel_private_group ?? []),
  ];
}
