import type {
  ChannelPreview,
  InitMessagingResponse,
  Member,
  PollEnvelope,
  RemoteChannel,
} from "../types";
import { defaultEndpoints, type MessengerEndpoints } from "./endpoints";
import type { MessengerHttpClient, MessengerRequestInit } from "./http";
import { fetchInitMessaging, flattenChannelSlots } from "./initMessaging";
import { fetchLongPoll } from "./longPoll";
import { fetchChannelPreview } from "./channelPreview";
import { fetchCanMessagePartners } from "./searchPartners";

export interface MessengerTransport {
  initMessaging(): Promise<InitMessagingResponse>;
  loadChannels(): Promise<RemoteChannel[]>;
  longPoll(last: number, init?: MessengerRequestInit): Promise<PollEnvelope[]>;
  channelPreview(channelIds: number[]): Promise<ChannelPreview[]>;
  canMessagePartners(): Promise<Member[]>;
}

export interface TransportConfig {
  http: MessengerHttpClient;
  endpoints?: Partial<MessengerEndpoints>;
}

export function createTransport(config: TransportConfig): MessengerTransport {
  const { http } = config;
  const endpoints: MessengerEndpoints = { ...defaultEndpoints, ...config.endpoints };

  return {
    initMessaging: () => fetchInitMessaging(http, endpoints),
    async loadChannels() {
      const response = await fetchInitMessaging(http, endpoints);
      return flattenChannelSlots(response.channel_slots);
    },
    longPoll: (last, init) => fetchLongPoll(http, endpoints, last, init),
    channelPreview: (channelIds) => fetchChannelPreview(http, endpoints, channelIds),
    canMessagePartners: () => fetchCanMessagePartners(http, endpoints),
  };
}

export { defaultEndpoints, BUS_INACTIVITY } from "./endpoints";
export type { MessengerEndpoints } from "./endpoints";
export type { MessengerHttpClient, MessengerRequestInit } from "./http";
export { flattenChannelSlots } from "./initMessaging";
