import { toPreviewText } from "../utils/html";
import type { NotificationHost } from "./NotificationHost";
import type { IncomingMessagePayload } from "./types";

export interface NotificationControllerDeps {
  host?: NotificationHost;
  getUnreadTotal: () => Promise<number>;
}

export interface NotificationController {
  onIncomingMessage(payload: IncomingMessagePayload): void;
  refreshBadge(): Promise<void>;
}

export function createNotificationController(
  deps: NotificationControllerDeps,
): NotificationController {
  const { host, getUnreadTotal } = deps;

  async function refreshBadge() {
    if (!host?.setBadge) return;
    await host.setBadge(await getUnreadTotal());
  }

  return {
    onIncomingMessage(payload) {
      if (payload.isChannelOpen) {
        void refreshBadge();
        return;
      }

      const title = payload.channelName ?? payload.message.author_id?.[1] ?? "";
      const body = toPreviewText(payload.message.body);

      if (payload.visibility === "foreground") {
        host?.showInApp?.({ channelId: payload.channelId, title, body });
      } else {
        void host?.showLocal?.({ channelId: payload.channelId, title, body });
      }

      void refreshBadge();
    },

    refreshBadge,
  };
}
