import type { MessengerDb } from "../db/client";
import type { NewMessageRow } from "../db/schema";
import type { ChangeBus } from "../events/changeBus";
import type { Message, MessageStatus } from "../types";
import { nowIso } from "../utils/time";

export interface StoredMessage {
  id: number;
  channelId: number;
  body: string;
  date: string | null;
  authorId: number | null;
  authorName: string | null;
  messageType: string | null;
  status: MessageStatus | null;
}

export interface MessageRepository {
  upsertMessages(channelId: number, messages: Message[], status?: MessageStatus): Promise<void>;
  listByChannel(channelId: number, limit?: number): Promise<StoredMessage[]>;
}

function toMessageRow(channelId: number, message: Message, now: string, status?: MessageStatus): NewMessageRow {
  return {
    id: message.id,
    channel_id: channelId,
    body: message.body ?? "",
    date: message.date ?? null,
    author_id: message.author_id?.[0] ?? null,
    author_name: message.author_id?.[1] ?? null,
    message_type: message.message_type ?? null,
    status: status ?? message.status ?? null,
    temp_id: null,
    attachments: JSON.stringify(message.attachment_ids ?? []),
    updated_at: now,
  };
}

export function createMessageRepository(db: MessengerDb, bus: ChangeBus): MessageRepository {
  return {
    async upsertMessages(channelId, messages, status) {
      if (!messages.length) return;
      const now = nowIso();
      const rows = messages.map((message) => toMessageRow(channelId, message, now, status));

      await db
        .insertInto("messenger_message")
        .values(rows)
        .onConflict((oc) =>
          oc.column("id").doUpdateSet((eb) => ({
            body: eb.ref("excluded.body"),
            date: eb.ref("excluded.date"),
            author_id: eb.ref("excluded.author_id"),
            author_name: eb.ref("excluded.author_name"),
            message_type: eb.ref("excluded.message_type"),
            status: eb.ref("excluded.status"),
            attachments: eb.ref("excluded.attachments"),
            updated_at: eb.ref("excluded.updated_at"),
          })),
        )
        .execute();

      bus.emit("messenger_message");
    },

    async listByChannel(channelId, limit = 50) {
      const rows = await db
        .selectFrom("messenger_message")
        .selectAll()
        .where("channel_id", "=", channelId)
        .orderBy("date", "desc")
        .limit(limit)
        .execute();

      return rows
        .map((row) => ({
          id: row.id,
          channelId: row.channel_id,
          body: row.body,
          date: row.date,
          authorId: row.author_id,
          authorName: row.author_name,
          messageType: row.message_type,
          status: (row.status as MessageStatus | null) ?? null,
        }))
        .reverse();
    },
  };
}
